// window-bar.mjs — the main-process half of the window bar (UisBarWindow), shared by every yaiol Electron app
// whose window has no system frame.
//
// ⚠ NEVER hand-edit an app's copy — it is generated by the shared catalog's sync
//    from the canonical source. Edit the canonical file and re-sync.
//
// The page draws the bar; only the main process can act on the window. So the bar's three buttons call the
// routes below, and the window tells the page whenever it becomes maximized or stops being so (the button is
// one way among several: a snap, a double click on the bar, a keyboard shortcut).
//
//   registerWindowRoutes(api, () => mainWindow);   // once, with the other routes
//   watchWindowState(mainWindow);                   // once per window, right after it is created
//
// The window itself is created with `frame: false`.

// The routes the bar calls. `getWindow` returns the app's window (or null while there is none).
export function registerWindowRoutes(api, getWindow) {
  const current = () => {
    const win = getWindow();
    return win && !win.isDestroyed() ? win : null;
  };
  api.get("/window-state", (req, res) => {
    res.json({ maximized: !!current()?.isMaximized() });
  });
  api.post("/window-minimize", (req, res) => {
    current()?.minimize();
    res.json({ ok: true });
  });
  // One route for both states: it maximizes a normal window and restores a maximized one.
  api.post("/window-maximize", (req, res) => {
    const win = current();
    if (win) {
      if (win.isMaximized()) win.unmaximize(); else win.maximize();
    }
    res.json({ ok: true });
  });
  api.post("/window-close", (req, res) => {
    res.json({ ok: true });
    current()?.close();
  });
}

// Tells the page each time the window becomes maximized or stops being so: a `uis-window-state` event on
// `window`, with `detail.maximized`. No preload is involved.
export function watchWindowState(win) {
  const tell = () => {
    if (win.isDestroyed()) return;
    win.webContents
      .executeJavaScript(`window.dispatchEvent(new CustomEvent('uis-window-state', { detail: { maximized: ${win.isMaximized()} } }))`)
      .catch(() => {});
  };
  win.on("maximize", tell);
  win.on("unmaximize", tell);
  watchTitleBarColour(win);
}

// The bar is painted like the system's own title bars. Windows has an accent colour and a switch "show the
// accent colour on title bars and window borders": with the switch on, the bar of the ACTIVE window takes that
// colour (an inactive title bar is neutral); with it off, or on another system, the bar keeps its own colours.
// The page is given the three properties the bar's stylesheet reads, or has them removed. Read again each time
// the window comes to the front, so a colour changed in the system's settings shows on return.
const BAR_PROPERTIES = ["--uis-win-bar-bgd", "--uis-win-bar-text", "--uis-win-bar-hov"];

function watchTitleBarColour(win) {
  if (process.platform !== "win32") return;
  const paint = (colours) => {
    if (win.isDestroyed()) return;
    const calls = BAR_PROPERTIES.map((name, i) => (colours ? `s.setProperty('${name}','${colours[i]}')` : `s.removeProperty('${name}')`));
    win.webContents.executeJavaScript(`{ const s = document.documentElement.style; ${calls.join("; ")}; }`).catch(() => {});
  };
  const refresh = async () => {
    const rgb = win.isDestroyed() || !win.isFocused() ? null : await titleBarColour();
    paint(rgb && win.isFocused() ? barColours(rgb) : null);
  };
  win.on("focus", refresh);
  win.on("blur", refresh);
  // A page that loads (or reloads) starts without the properties.
  win.webContents.on("did-finish-load", refresh);
}

// The system's title-bar colour as [red, green, blue], or null when title bars are not coloured. Both values
// are the window manager's own settings: the switch (1 = on) and the colour, stored blue-green-red.
async function titleBarColour() {
  const { execFile } = await import("node:child_process");
  const text = await new Promise((resolve) => {
    execFile("reg", ["query", "HKCU\\Software\\Microsoft\\Windows\\DWM"], { windowsHide: true }, (err, out) => resolve(err ? "" : out));
  });
  const dword = (name) => {
    const found = new RegExp(`^\\s*${name}\\s+REG_DWORD\\s+0x([0-9a-f]+)`, "im").exec(text);
    return found ? parseInt(found[1], 16) : null;
  };
  const abgr = dword("AccentColor");
  if (dword("ColorPrevalence") !== 1 || abgr === null) return null;
  return [abgr & 0xff, (abgr >>> 8) & 0xff, (abgr >>> 16) & 0xff];
}

// The three values the bar takes for a title-bar colour: its background, the text and icons on it (light on a
// dark colour, dark on a light one) and a button's background under the pointer.
export function barColours([r, g, b]) {
  // Perceived brightness (the usual weights for red, green and blue), 0 = black, 255 = white.
  const brightness = Math.floor((299 * r + 587 * g + 114 * b) / 1000);
  const hex = (n) => n.toString(16).padStart(2, "0");
  const [text, hover] = brightness < 150 ? ["#ffffff", "rgba(255,255,255,0.18)"] : ["#1a1a1a", "rgba(0,0,0,0.12)"];
  return [`#${hex(r)}${hex(g)}${hex(b)}`, text, hover];
}
